/* Supabase-backed accounts. No authentication is simulated when unconfigured. */
const config=window.MURMUR_AUTH_CONFIG||{};
const gate=document.getElementById('authGate');
const appRoot=document.querySelector('.app');
const keys=['murmur-sounds','murmur-scenes','murmur-relaxed-seconds'];
let client,user,revision=0,values={},dirty=false,syncing=false,conflict=false,syncTimer,appReady=false;
let mode='login';
const configured=(()=>{try{const key=config.publishableKey;if(!key||key.startsWith('sb_secret_'))return false;if(key.split('.').length===3){const payload=JSON.parse(atob(key.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));if(payload.role!=='anon')return false}return new URL(config.url).protocol==='https:'}catch{return false}})();
function authMessage(text){document.getElementById('authMessage').textContent=text}
function cacheKey(){return 'murmur-account-cache:'+user.id}
function validPayload(input){const result={};for(const k of keys){const v=input?.[k];if(typeof v==='string'){try{const data=JSON.parse(v);if(k==='murmur-relaxed-seconds'?(typeof data==='number'&&Number.isFinite(data)&&data>=0):Array.isArray(data))result[k]=v}catch{}}}return result}
function cache(){try{localStorage.setItem(cacheKey(),JSON.stringify({revision,values,dirty}))}catch{setStatus('当前设备无法缓存，请及时同步云端')}}
function setStatus(text){window.murmurSyncStatus=text;const node=document.getElementById('syncStatus');if(node)node.textContent=text}
async function sync(){if(!dirty||syncing||!user||conflict)return;syncing=true;let succeeded=false;const snapshot=JSON.stringify(values);setStatus('正在同步…');try{const {data,error}=await client.rpc('save_murmur_account',{expected_revision:revision,new_payload:JSON.parse(snapshot)});if(error)throw error;if(!data?.length){conflict=true;throw Error('conflict')}revision=Number(data[0].revision);dirty=JSON.stringify(values)!==snapshot;cache();succeeded=true;setStatus(dirty?'还有内容待同步':'已同步至账号')}catch(e){setStatus(conflict?'其他设备已有更新。请先导出本机备份，再重新加载云端数据。':'同步失败，数据暂存本机，可点击“重试同步”。')}finally{syncing=false;if(dirty&&!conflict&&succeeded)scheduleSync()}}
function scheduleSync(){clearTimeout(syncTimer);syncTimer=setTimeout(sync,1500)}
window.murmurStore={getItem:k=>values[k]??null,setItem:(k,v)=>{if(!user||conflict)throw Error('Account not writable');if(!keys.includes(k))return;if(values[k]===String(v))return;values[k]=String(v);dirty=true;cache();scheduleSync()}};
function exportBackup(){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),data:values},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='murmur-account-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function parseSocialLinks(text){const found=String(text).match(/https?:\/\/[^\s<>"，。！）)]+/g)||[];const items=[],seen=new Set();for(let raw of found){raw=raw.replace(/[;；、]+$/,'');let u;try{u=new URL(raw)}catch{continue}const h=u.hostname.toLowerCase();let platform;if(['v.douyin.com','www.douyin.com','douyin.com'].includes(h))platform='抖音';else if(['xhslink.com','www.xiaohongshu.com','xiaohongshu.com'].includes(h))platform='小红书';else continue;if(u.username||u.password||u.port)continue;if((h.includes('douyin')&&h!=='v.douyin.com'&&!/^\/(video|note)\/\d+/.test(u.pathname))||(h.includes('xiaohongshu')&&!/^\/(explore|discovery\/item)\//.test(u.pathname)))continue;u.protocol='https:';u.hash='';if(seen.has(u.href))continue;seen.add(u.href);items.push({title:platform+'收藏 '+(items.length+1),url:u.href,scene:'睡眠',type:'external'})}return items}

function openCollectionImport(){let d=document.getElementById('collectionImportDialog');if(!d){d=document.createElement('dialog');d.id='collectionImportDialog';d.innerHTML='<form id="collectionImportForm"><div class="sheet-head"><h2>导入平台内容</h2><button type="button" id="closeCollectionImport" aria-label="关闭">×</button></div><label>分享链接或文案<textarea id="collectionUrl" required rows="5" placeholder="粘贴 B 站公开收藏夹链接，或抖音／小红书分享文案，可一次粘贴多个作品链接"></textarea></label><p class="note">B 站：批量导入公开收藏夹。抖音／小红书：导入分享文案中的作品链接，暂不读取整个收藏夹。短链接保留原样，暂用平台名称命名；声音仍在原平台播放。</p><p id="collectionImportStatus" class="sync-status" role="status"></p><button type="submit" class="primary" id="startCollectionImport">一键导入</button></form>';document.body.append(d);document.getElementById('closeCollectionImport').onclick=()=>d.close();document.getElementById('collectionImportForm').onsubmit=async e=>{e.preventDefault();const button=document.getElementById('startCollectionImport'),status=document.getElementById('collectionImportStatus');if(button.disabled)return;try{if(conflict)throw Error('请先在账号中处理多设备同步冲突');const url=document.getElementById('collectionUrl').value.trim();const social=parseSocialLinks(url);if(social.length){const added=window.applySoundImport({items:social});await sync();status.textContent='已加入 '+added.added+' 条分享链接，重复 '+added.skipped+' 条。'+(dirty?'暂存本机，等待同步。':'已同步到当前账号。');button.textContent='继续导入';return}const parsed=new URL(url);if(parsed.hostname!=='space.bilibili.com'||!parsed.searchParams.get('fid'))throw Error('请复制具体的 B 站公开收藏夹完整链接');button.disabled=true;button.textContent='正在读取…';status.textContent='正在读取收藏夹，请稍候。完成前请勿切换账号。';const session=await client.auth.getSession();if(!session.data.session)throw Error('请先重新登录');const result=await client.functions.invoke('import-bilibili',{body:{url}});if(result.error){let reason='导入服务暂不可用，请确认服务已部署或稍后重试';try{const body=await result.error.context?.json();if(body?.error)reason=body.error}catch{}throw Error(reason)}if(!Array.isArray(result.data?.items))throw Error('返回的数据不完整，请重试');if(!appReady||!user||session.data.session.user.id!==user.id)throw Error('账号已切换，请重新导入');const imported=window.applySoundImport(result.data);await sync();status.textContent='已加入 '+imported.added+' 条，跳过重复 '+imported.skipped+' 条、失效 '+(result.data.invalid||0)+' 条。'+(dirty?'已暂存本机，请到账号中重试同步。':'已同步到当前账号。');button.textContent='再次导入'}catch(error){status.textContent=error.message||'导入失败，请稍后重试';button.textContent='重试导入'}finally{button.disabled=false}}}const old=document.getElementById('accountDialog');if(old?.open)old.close();d.showModal()}

function showAccount(){let d=document.getElementById('accountDialog');if(!d){d=document.createElement('dialog');d.id='accountDialog';d.innerHTML='<div class="sheet-head"><h2>我的账号</h2><button id="closeAccount" aria-label="关闭">×</button></div><p class="account-info" id="accountEmail"></p><p id="syncStatus" class="sync-status" role="status"></p><div class="account-actions"><button id="retrySync">重试同步</button><button id="importPublicCollection">一键导入公开收藏夹</button><button id="importSounds">导入收藏文件</button><input id="soundImportFile" type="file" accept=".json,application/json" hidden><button id="accountBackup">导出本机备份</button><button id="loadCloud">重新加载云端数据</button><button id="logout">退出登录</button></div>';document.body.append(d);document.getElementById('closeAccount').onclick=()=>d.close();document.getElementById('retrySync').onclick=sync;document.getElementById('accountBackup').onclick=exportBackup;document.getElementById('importPublicCollection').onclick=openCollectionImport;document.getElementById('importSounds').onclick=()=>document.getElementById('soundImportFile').click();document.getElementById('soundImportFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(conflict)throw Error('请先导出备份并解决多设备同步冲突');if(file.size>1048576)throw Error('文件超过 1 MB，请分批导入');const input=JSON.parse(await file.text());const result=window.applySoundImport(input);await sync();const note='已加入 '+result.added+' 条，重复 '+result.skipped+' 条，无效 '+result.invalid+' 条。';setStatus(note+(dirty?'尚未同步，请点击重试同步。':'已保存到当前账号。'))}catch(error){setStatus(error instanceof SyntaxError?'文件不是有效 JSON，请重新选择。':error.message||'导入失败，请重试')}finally{e.target.value=''}};document.getElementById('loadCloud').onclick=()=>{if(dirty&&!confirm('这会放弃尚未同步的本机更改，请先导出备份。继续吗？'))return;localStorage.removeItem(cacheKey());location.reload()};document.getElementById('logout').onclick=async()=>{if(window.recordUsage)window.recordUsage(true);await sync();if(dirty&&!confirm('有数据尚未同步。退出后仍保留在此设备的账号缓存中，是否继续？'))return;window.halt?.();appReady=false;appRoot.hidden=true;const {error}=await client.auth.signOut({scope:'local'});if(error){appRoot.hidden=false;appReady=true;setStatus('退出失败，请重试');return}location.reload()}}document.getElementById('accountEmail').textContent=user.email;setStatus(window.murmurSyncStatus||'已同步至账号');d.showModal()}
function loadScript(path){return new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=path;s.onload=resolve;s.onerror=reject;document.body.append(s)})}
async function boot(session){if(appReady)return;user=session.user;const {data,error}=await client.from('murmur_accounts').select('payload,revision').eq('user_id',user.id).maybeSingle();if(error)throw error;revision=Number(data?.revision||0);values=validPayload(data?.payload);let prior;try{prior=JSON.parse(localStorage.getItem(cacheKey())||'null')}catch{}if(prior?.dirty){if(Number(prior.revision)!==revision){conflict=true;values=validPayload(prior.values);setStatus('云端已有更新，请导出本机备份后重新加载云端数据')}else{values=validPayload(prior.values);dirty=true}}else setStatus('已同步至账号');cache();appReady=true;gate.hidden=true;appRoot.hidden=false;await loadScript('app.js');const tools=document.createElement('div');tools.className='header-tools';const add=document.getElementById('addTop');add.before(tools);tools.append(add);const account=document.createElement('button');account.className='account-button';account.textContent='账号';account.onclick=showAccount;tools.prepend(account);const importButton=document.createElement('button');importButton.className='account-button';importButton.textContent='导入收藏';importButton.onclick=openCollectionImport;tools.append(importButton);if(dirty&&!conflict)scheduleSync();if(conflict)showAccount()}
function chooseMode(next){mode=next;document.querySelectorAll('[data-auth-mode]').forEach(b=>b.classList.toggle('active',b.dataset.authMode===mode));document.getElementById('authSubmit').textContent=mode==='login'?'登录':'创建账号';document.getElementById('authPassword').autocomplete=mode==='login'?'current-password':'new-password';authMessage('')}
document.querySelectorAll('[data-auth-mode]').forEach(b=>b.onclick=()=>chooseMode(b.dataset.authMode));
document.getElementById('authForm').onsubmit=async e=>{e.preventDefault();if(!client){authMessage('账号服务尚未配置，当前不能注册或登录。');return}const email=document.getElementById('authEmail').value.trim(),password=document.getElementById('authPassword').value;const button=document.getElementById('authSubmit');button.disabled=true;authMessage('正在处理…');try{const result=mode==='login'?await client.auth.signInWithPassword({email,password}):await client.auth.signUp({email,password,options:{emailRedirectTo:location.origin+location.pathname}});if(result.error)throw result.error;document.getElementById('authPassword').value='';if(result.data.session)await boot(result.data.session);else authMessage('请到邮箱查收确认邮件，确认后回来登录。')}catch{authMessage(mode==='login'?'登录失败，请检查邮箱、密码与邮箱验证状态后重试。':'注册未完成，请检查邮箱、密码要求或稍后重试。')}finally{button.disabled=false}};
async function init(){if(!configured){authMessage('账号服务尚未配置，暂时不能注册或登录。');return}try{if(!window.supabase?.createClient)throw Error('SDK not loaded');client=window.supabase.createClient(config.url,config.publishableKey);const {data,error}=await client.auth.getSession();if(error)throw error;if(data.session){const check=await client.auth.getUser();if(check.error)throw check.error;await boot({...data.session,user:check.data.user})}client.auth.onAuthStateChange((event,session)=>{if(appReady&&(event==='SIGNED_OUT'||(session&&session.user.id!==user.id))){window.halt?.();appRoot.hidden=true;location.reload()}})}catch{appReady=false;appRoot.hidden=true;gate.hidden=false;authMessage('账号服务连接失败，请检查网络或服务配置后刷新。')}}
init();
